    for j in range(n):
        solver.add(z3.And(grid(i, j) >= 0, grid(i, j) <= n-1))

# Latin square: each row is a permutation
for i in range(n):
    for j1 in range(n):
        for j2 in range(j1+1, n):
            solver.add(grid(i, j1) != grid(i, j2))

# Each column is a permutation
for j in range(n):
    for i1 in range(n):
        for i2 in range(i1+1, n):
