# Let's try a more efficient Z3 encoding using the Array theory
import z3

n = 7

# Create a 2D array using Z3's Array theory
# We'll use a flat array: grid[i*n + j] = value
grid = z3.Array('grid', z3.IntSort(), z3.IntSort())

solver = z3.Solver()

# Domain constraints
for i in range(n):
    for j in range(n):
        idx = i * n + j
        solver.add(z3.And(z3.Select(grid, idx) >= 0, z3.Select(grid, idx) <= n-1))

# Latin square: each row is a permutation
for i in range(n):
    for j1 in range(n):
        for j2 in range(j1+1, n):
            solver.add(z3.Select(grid, i*n + j1) != z3.Select(grid, i*n + j2))

# Each column is a permutation
for j in range(n):
    for i1 in range(n):
        for i2 in range(i1+1, n):
            solver.add(z3.Select(grid, i1*n + j) != z3.Select(grid, i2*n + j))

# Idempotent diagonal
for i in range(n):
    solver.add(z3.Select(grid, i*n + i) == i)

# QG3: x[x[i][j]][x[j][i]] = i
# We need to express: grid[grid[i*n + j] * n + grid[j*n + i]] == i
for i in range(n):
    for j in range(n):
        a = z3.Select(grid, i*n + j)
        b = z3.Select(grid, j*n + i)
        idx = a * n + b
        solver.add(z3.Select(grid, idx) == i)

print("Solving with Array theory...")
result = solver.check()
print(result)
if result == z3.sat:
    m = solver.model()
    grid_vals = [[m.evaluate(z3.Select(grid, i*n + j)).as_long() for j in range(n)] for i in range(n)]
    for row in grid_vals:
        print(row)
    flat = [grid_vals[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSAT")

