# Variable encoding: var[i][j][k] means grid[i][j] == k
# We'll use a flat variable numbering

def var_id(i, j, k):
    return i * n * n + j * n + k + 1  # 1-indexed for SAT

num_vars = n * n * n

clauses = []

# Each cell has at least one value
for i in range(n):
    for j in range(n):
        clauses.append([var_id(i, j, k) for k in range(n)])

# Each cell has at most one value (pairwise)
for i in range(n):
    for j in range(n):
        for k1 in range(n):
            for k2 in range(k1+1, n):
                clauses.append([-var_id(i, j, k1), -var_id(i, j, k2)])

# Each row has all values (at least one of each)
for i in range(n):
    for k in range(n):
        clauses.append([var_id(i, j, k) for j in range(n)])

# Each column has all values
for j in range(n):
    for k in range(n):
        clauses.append([var_id(i, j, k) for i in range(n)])

# Idempotent diagonal
for i in range(n):
    clauses.append([var_id(i, i, i)])

# QG3: x[x[i][j]][x[j][i]] = i
# For each i, j, a, b: if x[i][j]=a and x[j][i]=b then x[a][b]=i
# This is: (x[i][j]=a) AND (x[j][i]=b) => (x[a][b]=i)
# In CNF: (-x[i][j]=a) OR (-x[j][i]=b) OR (x[a][b]=i)
