import z3

n = 7

# Use boolean variables
B = [[[z3.Bool(f'b_{i}_{j}_{k}') for k in range(n)] for j in range(n)] for i in range(n)]

solver = z3.Solver()

# Each cell has exactly one value
for i in range(n):
    for j in range(n):
        solver.add(z3.PbEq([(B[i][j][k], 1) for k in range(n)], 1))

# Each row has all values
for i in range(n):
    for k in range(n):
        solver.add(z3.PbEq([(B[i][j][k], 1) for j in range(n)], 1))

# Each column has all values
for j in range(n):
    for k in range(n):
        solver.add(z3.PbEq([(B[i][j][k], 1) for i in range(n)], 1))

# Idempotent diagonal
for i in range(n):
    solver.add(B[i][i][i])

# QG3: x[x[i][j]][x[j][i]] = i
# For each i,j,a,b: if x[i][j]=a and x[j][i]=b then x[a][b]=i
# In boolean: (B[i][j][a] and B[j][i][b]) => B[a][b][i]
# Which is: (not B[i][j][a]) or (not B[j][i][b]) or B[a][b][i]
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                solver.add(z3.Or(z3.Not(B[i][j][a]), z3.Not(B[j][i][b]), B[a][b][i]))

print("Solving with boolean encoding...")
result = solver.check()
print(result)
if result == z3.sat:
    m = solver.model()
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if m.evaluate(B[i][j][k]):
                    grid[i][j] = k
                    break
    for row in grid:
        print(row)
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSAT")
